def alerte(temp):
    if temp >= 90:
        return "CRITIQUE"
    elif temp >= 60:
        return "CHAUD"
    else:
        return "OK"

def compter_erreurs(lignes):
    total = 0
    for ligne in lignes:
        if ligne.strip().startswith("ERROR"):
            total += 1
    return total

def capteurs_hs(mesures):
    hs = []
    for nom, valeur in mesures.items():
        if valeur is None or valeur < 0:
            hs.append(nom)
    return sorted(hs)

def ordre_redemarrage(modules):
    tries = sorted(modules, key=lambda m: (m[1], m[0]))
    return [nom for nom, priorite in tries]

def rapport(journal):
    compte = {}
    for ligne in journal.splitlines():
        mots = ligne.split()
        if len(mots) < 3:
            continue
        module, niveau = mots[1], mots[2]
        if niveau == "ERROR":
            compte[module] = compte.get(module, 0) + 1
    return compte
